import React, { useState } from "react";
import { X, Send, Copy, Check, ExternalLink, Sparkles, Heart } from "lucide-react";

export default function PublishModal({ isOpen, onClose, templateSlug, draftTitle, customContent }) {
    const [senderName, setSenderName] = useState("");
    const [whatsappNumber, setWhatsappNumber] = useState("");
    const [partnerName, setPartnerName] = useState("");
    const [customSlug, setCustomSlug] = useState("");
    const [generatedLink, setGeneratedLink] = useState("");
    const [copied, setCopied] = useState(false);

    if (!isOpen) return null;

    const handleGenerate = (e) => {
        e.preventDefault();

        // Generate clean URL slug
        const slugPart = customSlug.trim()
            ? customSlug.toLowerCase().replace(/[^a-z0-9-]/g, "-")
            : `${senderName || "love"}-and-${partnerName || "forever"}`.toLowerCase().replace(/[^a-z0-9-]/g, "-");

        const payload = {
            senderName: senderName || "Someone Special",
            partnerName: partnerName || "My Love",
            whatsappNumber,
            templateSlug,
            content: customContent || {},
            publishedAt: new Date().toISOString()
        };

        // Save locally for instant persistence
        try {
            localStorage.setItem(`lws:published:${templateSlug}:${slugPart}`, JSON.stringify(payload));
        } catch {
            /* ignore */
        }

        // Encode content into URL string so link works anywhere!
        let encodedData = "";
        try {
            const jsonStr = JSON.stringify(customContent || {});
            encodedData = encodeURIComponent(btoa(unescape(encodeURIComponent(jsonStr))));
        } catch {
            encodedData = "";
        }

        const baseUrl = window.location.origin;
        const fullLink = `${baseUrl}/v/${slugPart}?slug=${templateSlug}&d=${encodedData}`;

        setGeneratedLink(fullLink);
    };

    const handleCopy = () => {
        if (!generatedLink) return;
        navigator.clipboard.writeText(generatedLink);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
    };

    // Mailto link containing full details & the generated live link
    const emailSubject = encodeURIComponent(`New Website Order - ${senderName || "Customer"} & ${partnerName || "Partner"}`);
    const emailBody = encodeURIComponent(
        `Hi Love Website Studio!\n\nI have customized my romantic website draft and generated my live link.\n\n` +
        `👤 Customer Name: ${senderName || "N/A"}\n` +
        `📱 WhatsApp Number: ${whatsappNumber || "N/A"}\n` +
        `💑 Couple: ${senderName || "Me"} & ${partnerName || "My Partner"}\n` +
        `🎨 Template: ${templateSlug}\n\n` +
        `🔗 GENERATED CUSTOMIZED WEBSITE LINK:\n${generatedLink}\n\n` +
        `Please confirm payment details and activate my custom live link.\n\nThank you!`
    );

    const mailtoUrl = `mailto:lovewebsitestudio@gmail.com?subject=${emailSubject}&body=${emailBody}`;

    // WhatsApp order URL
    const whatsappText = encodeURIComponent(
        `Hi Love Website Studio! 💖 I customized my romantic website.\n\n` +
        `👤 *Name*: ${senderName}\n` +
        `💑 *Couple*: ${senderName} & ${partnerName}\n` +
        `🔗 *Personal Website Link*:\n${generatedLink}\n\n` +
        `Please share payment details to publish my website!`
    );
    const whatsappUrl = `https://wa.me/?text=${whatsappText}`;

    return (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md flex items-center justify-center p-4 z-50 animate-fadeIn">
            <div className="bg-[#181114] border border-pink-500/30 rounded-2xl p-6 max-w-md w-full text-center relative shadow-2xl overflow-y-auto max-h-[90vh]">
                <button
                    onClick={onClose}
                    className="absolute top-4 right-4 text-neutral-400 hover:text-white transition-colors"
                >
                    <X size={18} />
                </button>

                <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-pink-500/10 border border-pink-500/20 text-pink-300 text-xs font-medium mb-3">
                    <Sparkles size={12} /> Personal Website Publisher
                </div>

                <h3 className="font-display text-2xl text-white mb-1">
                    {generatedLink ? "Your Link is Ready! 🎉" : `Publish ${draftTitle || "Website"}`}
                </h3>
                <p className="text-neutral-400 text-xs mb-5">
                    {generatedLink
                        ? "Here is the customized private website link for your partner!"
                        : "Generate your partner's personal link and send order details directly to Love Website Studio."}
                </p>

                {!generatedLink ? (
                    <form onSubmit={handleGenerate} className="space-y-4 text-left">
                        <div>
                            <label className="block text-xs font-semibold text-neutral-300 mb-1">
                                Your Name
                            </label>
                            <input
                                type="text"
                                required
                                placeholder="e.g. Rahul"
                                value={senderName}
                                onChange={(e) => setSenderName(e.target.value)}
                                className="w-full bg-neutral-900/80 border border-white/10 rounded-xl px-3.5 py-2 text-sm text-white focus:outline-none focus:border-pink-500"
                            />
                        </div>

                        <div>
                            <label className="block text-xs font-semibold text-neutral-300 mb-1">
                                Your WhatsApp / Contact Number
                            </label>
                            <input
                                type="tel"
                                required
                                placeholder="e.g. +91 9876543210"
                                value={whatsappNumber}
                                onChange={(e) => setWhatsappNumber(e.target.value)}
                                className="w-full bg-neutral-900/80 border border-white/10 rounded-xl px-3.5 py-2 text-sm text-white focus:outline-none focus:border-pink-500"
                            />
                        </div>

                        <div>
                            <label className="block text-xs font-semibold text-neutral-300 mb-1">
                                Partner's Name
                            </label>
                            <input
                                type="text"
                                required
                                placeholder="e.g. Ananya"
                                value={partnerName}
                                onChange={(e) => setPartnerName(e.target.value)}
                                className="w-full bg-neutral-900/80 border border-white/10 rounded-xl px-3.5 py-2 text-sm text-white focus:outline-none focus:border-pink-500"
                            />
                        </div>

                        <div>
                            <label className="block text-xs font-semibold text-neutral-300 mb-1">
                                Custom Link Name (Optional)
                            </label>
                            <div className="flex items-center bg-neutral-900/80 border border-white/10 rounded-xl px-3 py-2 text-xs text-neutral-400">
                                <span className="text-neutral-500 mr-1">/v/</span>
                                <input
                                    type="text"
                                    placeholder={
                                        senderName && partnerName
                                            ? `${senderName.toLowerCase()}-and-${partnerName.toLowerCase()}`
                                            : "rahul-and-ananya"
                                    }
                                    value={customSlug}
                                    onChange={(e) => setCustomSlug(e.target.value)}
                                    className="bg-transparent text-white focus:outline-none w-full"
                                />
                            </div>
                        </div>

                        <button
                            type="submit"
                            className="w-full lws-btn-primary py-3 flex items-center justify-center gap-2 text-sm font-semibold mt-6"
                        >
                            <Heart size={15} className="text-pink-400 fill-pink-400" />
                            Generate Personal Link & Request Order
                        </button>
                    </form>
                ) : (
                    <div className="space-y-4 text-left animate-fadeIn">
                        {/* Generated Link Display Box */}
                        <div className="bg-black/60 border border-pink-500/40 rounded-xl p-3.5 space-y-2">
                            <span className="text-[10px] uppercase tracking-widest text-pink-300 font-semibold block">
                                🔗 Personal Shareable Link
                            </span>
                            <div className="text-xs font-mono text-neutral-200 break-all bg-neutral-900/80 p-2.5 rounded-lg border border-white/10">
                                {generatedLink}
                            </div>
                            <div className="flex gap-2 pt-1">
                                <button
                                    onClick={handleCopy}
                                    className="lws-btn-ghost text-xs py-1.5 px-3 flex-1 justify-center border border-white/10 hover:bg-white/10"
                                >
                                    {copied ? (
                                        <>
                                            <Check size={13} className="text-emerald-400" /> Copied!
                                        </>
                                    ) : (
                                        <>
                                            <Copy size={13} /> Copy Link
                                        </>
                                    )}
                                </button>
                                <a
                                    href={generatedLink}
                                    target="_blank"
                                    rel="noreferrer"
                                    className="lws-btn-ghost text-xs py-1.5 px-3 flex-1 justify-center border border-white/10 hover:bg-white/10"
                                >
                                    <ExternalLink size={13} /> Test Link
                                </a>
                            </div>
                        </div>

                        {/* Order Options */}
                        <div className="space-y-2.5 pt-2">
                            <p className="text-xs text-neutral-400 font-medium">
                                Send order request to Studio to activate link:
                            </p>
                            <a
                                href={mailtoUrl}
                                className="w-full lws-btn-primary py-3 flex items-center justify-center gap-2 text-sm font-semibold"
                            >
                                <Send size={15} /> Send Link to Studio via Email
                            </a>

                            <a
                                href={whatsappUrl}
                                target="_blank"
                                rel="noreferrer"
                                className="w-full bg-emerald-600 hover:bg-emerald-500 text-white rounded-xl py-2.5 flex items-center justify-center gap-2 text-xs font-semibold transition-colors"
                            >
                                📲 Send Link via WhatsApp
                            </a>
                        </div>
                    </div>
                )}

                <p className="text-[10px] text-neutral-500 mt-4">
                    Direct Studio Contact: lovewebsitestudio@gmail.com
                </p>
            </div>
        </div>
    );
}

import React, { useMemo } from "react";
import { useParams, useSearchParams, Link } from "react-router-dom";
import TemplateRenderer from "@/components/TemplateRenderer";
import { getTemplate } from "@/data/templateRegistry";
import { Heart, Sparkles } from "lucide-react";

export default function ViewWebsitePage() {
    const { shareId } = useParams();
    const [searchParams] = useSearchParams();

    const templateSlug = searchParams.get("slug") || "sunset-love";
    const encodedData = searchParams.get("d");

    const content = useMemo(() => {
        // First try decoding from URL parameter
        if (encodedData) {
            try {
                const decodedStr = decodeURIComponent(escape(atob(decodeURIComponent(encodedData))));
                return JSON.parse(decodedStr);
            } catch (e) {
                console.error("Failed to decode URL content data", e);
            }
        }

        // Fallback to localStorage lookup by shareId
        if (shareId) {
            try {
                const storedRaw = localStorage.getItem(`lws:published:${templateSlug}:${shareId}`);
                if (storedRaw) {
                    const parsed = JSON.parse(storedRaw);
                    return parsed.content || {};
                }
            } catch {
                /* ignore */
            }

            try {
                const draftRaw = localStorage.getItem(`lws:draft:${templateSlug}:demo`);
                if (draftRaw) {
                    return JSON.parse(draftRaw);
                }
            } catch {
                /* ignore */
            }
        }

        // Fallback to default demo data for template
        const entry = getTemplate(templateSlug);
        return entry?.config?.demoData || {};
    }, [shareId, templateSlug, encodedData]);

    return (
        <div className="relative min-h-screen">
            {/* Fullscreen Render of Partner's Custom Website */}
            <TemplateRenderer templateSlug={templateSlug} content={content} />

            {/* Subtle Romantic Studio Badge at Bottom */}
            <div className="fixed bottom-4 right-4 z-50">
                <Link
                    to="/"
                    target="_blank"
                    className="flex items-center gap-2 px-3.5 py-2 rounded-full bg-black/80 border border-pink-500/30 text-white/90 hover:text-pink-300 text-xs shadow-xl backdrop-blur-md transition-all hover:scale-105"
                >
                    <Heart size={13} className="text-pink-500 fill-pink-500 animate-pulse" />
                    <span>Created with <b>Love Website Studio</b></span>
                </Link>
            </div>
        </div>
    );
}

