import DashboardPage from "@/pages/DashboardPage";
import EditorPage from "@/pages/EditorPage";
import ViewWebsitePage from "@/pages/ViewWebsitePage";
import NotFoundPage from "@/pages/NotFoundPage";

function ScrollToTop() {
    const { pathname } = useLocation();
    useEffect(() => {
        window.scrollTo({ top: 0, behavior: "auto" });
    }, [pathname]);
    return null;
}

function Shell({ children, hideFooter = false }) {
    return (
        <div className="relative z-[2]">
            <Navbar />
            <main>{children}</main>
            {!hideFooter && <Footer />}
        </div>
    );
}

function App() {
    return (
        <div className="App">
            <BrowserRouter>
                <ScrollToTop />
                {/* Global Sleek Ambient Music Player */}
                <BackgroundMusic />

                <Routes>
                    <Route
                        path="/"
                        element={
                            <Shell>
                                <LandingPage />
                            </Shell>
                        }
                    />
                    <Route
                        path="/templates"
                        element={
                            <Shell>
                                <MarketplacePage />
                            </Shell>
                        }
                    />
                    <Route
                        path="/templates/:slug"
                        element={
                            <Shell>
                                <TemplateDetailsPage />
                            </Shell>
                        }
                    />
                    <Route
                        path="/dashboard"
                        element={
                            <Shell>
                                <DashboardPage />
                            </Shell>
                        }
                    />
                    <Route
                        path="/dashboard/websites/:slug/edit"
                        element={
                            <Shell hideFooter>
                                <EditorPage />
                            </Shell>
                        }
                    />
                    {/* Dynamic View Route for Customized Partner Websites */}
                    <Route path="/v/:shareId" element={<ViewWebsitePage />} />
